        "typeName": "单选题",
        "stem": "道德与法治课上。老师问同学们如果拾到钱包会怎样处理。几乎所有人都回答“上交给 警察或者老师”。老师又问同学们这样做的原因，有的同学说这样会被爸爸打”，也有的同 学说“这样妈妈和老师都会表扬我”。根据科尔伯格的发展阶段模型，这些同学现在最可能 处于道德发展的( )阶段。",
