        "stem": "某班级借鉴《乘风破浪的姐姐》，由学生们选出几名自律性较强的学生担任“组长”， 然后双向选择组队成团，在班级开启“团战”。“团战”采取积分的方式进行，上课认真， 作业工整等都可以获得积分卡，积分半个月奖励一次，学生可选择换座位等。这里运用的“积 分奖励”方法属于( )。",
