        "type": "single",
        "typeName": "单选题",
        "stem": "学生乐乐经常上课玩东西，班主任让他最后一个放学，老师就跟他约定，如果他能改 掉这个毛病的话，就可以跟其他同学一起放学，慢慢地乐乐改正了这一坏习惯。这里，班主 任采取的是（ ）",
