        "analysis": "本题考查冯忠良关于学习的分类。冯忠良将学习分为知识的学习、技能的学习 和社会规范 的学习，题干中小明听张老师讲新知识，属于知识的学习，在李老师指导 下完成实验属于技能的学 习，帮妈妈做小事属于社会规范的学习，故本题选 C。 29.【答案】B 本题考查班杜拉的观察学习。观察学习是指人通过观察他人（榜样）的行为及 其结果而习 得新行为的过程。班杜拉分析了观察学习的过程，认为这个过程包括注意 过程、保持过程、动作复 现过程和动机过程四个环节。（ 1）注意过程:注意并知觉榜 样情境的各个方面。（2）保持过程:记 住从榜样情境了解的行为，以表象和言语形式将 他们在记忆中进行表征、编码及储存。（3）动作复 现过程:复制从榜样情境中观察到的 行为。（4）动机过程:因表现所观察到的行为而受到激励。综上 所述，观察学习的第一 个子过程为注意过程，故本题选 B。 30.【答案】B 本题考查桑代克的联结-试误学习理论。该理论中桑代克认为学习的实质是刺 激与反应之间 建立联结，而学习的过程是尝试错误的过程。桑代克联结说认为学习有 三条主律：准备律、练习律 和效果律。准备律是指学习者在学习开始时的预备定势。 练习律是学会了的刺激-反应之间的联结， 练习和使用越多，联结就越强，反之联结则 减弱。题干中教师允许学生犯错误，并鼓励学生多尝试 从错误中学习，教师认为学习 的过程就是尝试错误的过程，这样获得的知识才会更加牢固，该观点 来自桑代克的联 结—试误理论，故本题选 B。 31.【答案】B 本题考查注意的品质。注意品质包括注意广度、注意稳定、注意分配和注意转 移。注意的 分配是指人在进行两种或多种活动时能把注意指向不同对象的现象。题干 中，能够同一时间清楚全 面把握统筹处理好真与假，虚与实，整体与局部等复杂关系， 说明其注意的分配能力较高，故本题 选 B 。"
