        "analysis": "本题考查知识的表征方式。知识的表征是指知识在头脑中的表示形式和组织结 构。知识表 征的方式有：概念、命题、命题网络、表象、图式。不同类型的知识在头 脑中的表征方式不同。 1. 概念： 概念代表着事物的基本属性和基本特征，是一种简 单的表征形式。比如“ 眼镜 ”就包含了这 样一些特征：有两个圆镜片，有两条眼镜 腿，用来矫正近视等等。2．命题和命题网络 命题是意义或观念的最小单元。用于表述 一个事实或描述一个状态，通常由一个关系和一个以上的论题组成。 命题用句子来表 达，但是命题不等于句子，一个句子可以包含一个或多个命题。两个或多个命题常 常 因为有某个共同的成分而相互联系在一起，从而构成了命题网络，或称为语义网络。命 题按层次 网络结构储存，相互有联系的信息组成网络。 3. 表象：人们头脑中形成的 与现实世界的情境相类 似的心理图像。同样的知识可以用不同的方式表征。。 4. 图式 是指有组织的知识结构。图式是关 于某个主题的一个知识单元，它包括与某主题相关 的一套相互联系的基本概念，构成了感知、理解 外界信息的框架结构。 综上所述， 本题选 B。"
