        "type": "multiple",
        "typeName": "多选题",
        "stem": "某中学教师刘某，因在同年的职称评定中没能晋升为一级教师。对该校的工 作失去了信心，于是向学校提出了请调报告，要求立即调走。因为正值学期中间， 而且刘某与学校签订的聘任合同还未到期，因而学校决定暂时不考虑刘某的调动 问题。为此，刘某拒不上课，致使其所任教的课程被迫停课。关于此案例，下列 说法错误的有",
