        "analysis": "教育制度的客观性是指：教育制度的制定虽然反映着人们的一些主观愿望和特 殊的价值需 求，但是，人们并不是也不可能随心所欲地制定或废止教育制度，某种教 育制度的制定或废止．有 它的客观基础和发展的规律性。这个客观基础和发展的规律 性主要是由社会生产力发展水平和人的 发展水平所决定的。教育机构的设置，层次类 型的分化，各级各类教育机构的制度化，都受生产力 发展水平和受教育者发展水平的 制约。故答案错误。"
