        "analysis": "本题考查对认知策略的理解。认知策略是学习者用以支配他自己的注意、学习、 记忆和思 维的有内在组织的才能，这种才能使得学习过程的执行控制成为可能。认知 策略与智慧技能的不同 在于智慧技能定向于学习者的外部环境，而认知策略则支配着 学习者在对付环境时其自身的行为， 即“ 内在的 ”东西。简单他说，认知策略就是 学习者用来“管理 ” 自己的学习过程的方式，即学会 如何学习，认知策略既是学习 的条件，又是学习的结果。故本题说法正确。"
