        "analysis": "本题考查技能的分类。操作技能又叫运动技能、动作技能，是通过学习而形成 的合乎法则 的操作活动方式。题干中打篮球是一种动作技能。动作技能可分为封闭性 技能和开放性技能。封闭 性技能是一种完全依赖内部肌肉反馈作为刺激指导的技能， 这种任务闭着眼睛也能完成。例如在黑 板上徒手快速划一个大圆就接近于封闭动作技 能。开放性技能，也称开放环路技能，主要依赖于周 围环境提供的信息，正确地感知 周围环境成为运动调节的重要因素。例如打篮球等，开放性技能要 求人们具有处理外 界信息变化的能力和对事件发生的预见能力。综上所述，在黑板上徒手画圆应属 于封 闭性技能，故本题说法错误。 87.【答案】正确 本题考查认知方式的教育意义。认知方式没有优劣好坏之分，只是表现为学生 对信息加工 方式的某种偏爱，主要影响学生的学习方式。智力是影响学习的一个重要 因素。在传统教学条件下， 智力是学习成绩的一个可靠的预测指标。然而，智力并不 影响学习能否发生，它主要影响学习的速 度、数量、巩固程度和学习的迁移。所有这 些认知差异表明，我们必须根据学生认知差异的特点与 作用，不断改革教学，做到因 材施教。首先，应该创设适应学生认知差异的教学组织形式。其次， 采用适应认知差 异的教学方式，努力使教学方式个别化。最后，运用适应认知差异的教学手段。故 本 题说法正确。"
