        "analysis": "个体身心发展的一般规律包括：（1）阶段性——个体在不同年龄阶段表现出不同的身心发展总体特征和主要矛盾，面临不同的发展任务，教育必须从学生的实际出发，针对不同年龄阶段的学生提出不同的教育任务和要求。」幼儿园小学化「正是忽视了幼儿阶段与小学阶段的不同发展特点，把小学阶段的内容和要求提前到幼儿阶段，违背了阶段性规律。（2）顺序性——身心发展由低级到高级、由简单到复杂、由量变到质变的连续发展过程，教育要循序渐进，不可「揠苗助长「。（3）差异性——不同个体在身心发展上存在差异，教育要因材施教。（4）互补性——个体某方面机能受损后可通过其他方面超常发展得到补偿，教育要长善救失。本题中「把小学内容提前给学龄前孩子「最直接违背的是阶段性规律，因为幼儿园和小学分属不同发展阶段，各阶段有各阶段的教育任务和内容。"
