        "type": "judge",
        "typeName": "判断题",
        "stem": "儿童的攻击性较强，常与其他儿童产生冲突，根据杜拉的社会认知理论，教师去了解这 些 儿童产生攻击性的原因时，应当从个人，行为和环境多个角度分析。",
