        "answer": "正确",
        "analysis": "本题考查对认知策略中的复述策略的理解。复述策略是指在工作记忆中为了保 持信 息，运用内部语言在大脑中重现学习材料或刺激， 以便将注意力维持在学习材料 上的方法。 它是短时记忆的信息进入长时记忆的关键。包括利用无意识记和有意识记、 排除抑制干扰、 整体记忆与分段记忆、多种感官参与、画线、朗读、默写等。题干中 小达为了记住单词，反 复在脑海中背诵记忆，属于复述策略，故本题说法正确。"
