        "stem": "教历史的孙老师善于语言表达，口才很好，他上历史课时引入大量的历史故事中的精彩典故。学生们十分爱听他的课，盼着上他的课，甚至把它当成了“说书人”，他一上台，学生们就在下边说“来一段，来一段”。但是一到历史期末考，许多学生不及格。学生平时光乐于听故事，一些基本的历史事件、年代、人物等基础知识都没掌握，复习时老师也没有进行系统的归纳，于是造成了这一结果。显然，这位老师只追求教学表面形式的精彩热闹，违背了教师运用教学艺术的宗旨。根据知识的分类，基本的历史事件、年代、人物属于（ ）。",
