        "analysis": "本题考查格雷戈克的学习风格分类。格雷戈克将学习者的学习风格分为具体—序列、具体—随机、抽象—序列和抽象—随机四种类型。（1）具体—序列型风格的学习者喜欢通过直接的动手经验学习，希望教学组织得井然有序；采用学习手册、程序教学、演示和有指导的实验练习，对他们的学习效果最佳。（2）具体—随机型风格的学习者能通过试误法，从探索经验中迅速得出结论；他们喜欢教学游戏、模拟，愿意独立承担设计项目。（3）抽象—序列型风格的学习者善于理解以逻辑序列呈示的词语或符号信息；他们喜欢通过阅读和听课的方式进行学习。（4）抽象—随机型风格的学习者特别善于从演讲中抓住要点，理解意思，并能对演讲者的声调和演说风格做出反应；对这类学习者来说，参加小组讨论，听穿插问答的讲授或是看电影和电视，可以取得较好的学习效果。题干信息“偏好阅读、听演讲等方式”可得知为抽象—序列型的学习风格。故本题选D。"
