        "stem": "对于纪律松散、不按时完成作业的学生，李老师从不姑息迁就，而是严肃处理，要求学生必须遵守学校纪律，按制度行事，同时“晓之以理，动之以情”，找学生谈话交流，帮助学生正视自己，从而激发学习兴趣和动力。李老师在教育学生的过程中，主要遵循了（ ）的原则。",
