        "analysis": "本题考查学习定义的理解。广义的学习指有机体在后天生活过程中，由于练习或反复经验而产生的行为或行为潜能的比较持久的变化。它包含动物的学习和人类的学习。学习是人与动物共有的普遍现象，但二者存在本质差异。人的学习不仅要掌握个体经验，而且要掌握社会经验；动物的学习缺乏社会性，只是一种个体行为。学习所引起的变化是相对持久的，有时候这种变化并不一定在行为上立刻表现出来，而是在日后才逐渐显现，即行为潜能的变化。学习是有机体后天习得经验的过程；需要注意的是，并不是所有的行为变化都是由学习引起的，由疲劳、疾病或药物等引起的行为的短暂变化与真正的学习行为是有区别的。故本题选AD。"
