        "analysis": "教育法的效力是指教育法的有效性，即法的保护力和约束力，一般包括三类：对人的效力、空间效力及时间效力。其中对人的效力是指法律适用于哪些人。这里各国的确定标准不一，有的采取属人原则，凡本国公民一律适用；也有的采取属地原则，在本国领域内的本国人和外国人一律有效；还有的以本国利益为标准，采取保护原则。我国采取的是以属地原则为主，以属人原则、保护原则为补充的折中原则，这也是当今许多国家所奉行的原则。我国教育法适用于全体中国公民及在中国境内的外国人和无国籍人。此外，我国《教育法》第二条规定，在中华人民共和国境内的各级各类教育，适用本法。故本题正确。"
