        "answer": "D",
        "analysis": "本题考查的是替代强化。班杜拉认为，在动机过程中，观察者的模仿动机存在三种来源：直接强化、替代 强化和自我强化。直接强化（外部强化）：个体直接体验到自己的行为后果而受到强化。替代性强化：观 察者因看到榜样受强化而受到的强化。自我强化：社会向个体传递某一行为标准，当个体的行为表现符合 甚至超过这一标准时，他就对自己的行为进行自我奖励。ABC选项中教师的做法都是直接强化，D选项符 合替代强化的概念。故本题选D。"
