        "answer": "A",
        "analysis": "教育不仅是教育学的研究对象，而且是教育学的生命之母。教育实践不仅孕育了作为一门知识的教育学， 教育实践还规训了作为一门学科的教育学。首先表现在教育实践孕育了作为一门知识的教育学。教育学作 为一门知识的历史要比教育学作为一门学科的历史悠久得多。故本题正确。"
