        "answer": "A",
        "analysis": "教学媒体是指在教学过程中承载和传递教学信息（包括知识和技能）的载体或工具。教学媒体是教学内容 的载体，是教学内容的表现形式，是师生之间传递信息的工具，如实物、口头语言、图表、图像以及动画 等。教学媒体往往要通过一定的物质手段来实现，如书本、板书、投影仪、录像以及计算机等。故本题正 确。"
