        "analysis": "一般迁移也称非特殊迁移、普遍迁移，是指一种学习中所习得的一般原理、原则和态度对另一种具体内容 学习的影响，即原理、原则和态度的具体应用。如获得基本的运算技能、阅读技能后运用到各种具体的学 科学习中。故本题正确。"
