        "type": "judge",
        "typeName": "判断题",
        "stem": "如果儿童判断事情好坏的衡量标准是做某事是否得到大众认可，即认可是好的，不认可是坏的，则其 处于科尔伯格的道德发展阶段论的前习俗水平阶段。",
