        "year": 2018,
        "type": "single",
        "typeName": "单选题",
        "stem": "小刚在学习正方形的时候，将正方形归结为于种长宽相等的长方形，因此正方形具 有长方形的一切特征。小刚的这一学习行为属于（ ）。",
