        "year": 2017,
        "type": "single",
        "typeName": "单选题",
        "stem": "在学生心目中，教师往往是全知全能的，他们经常向教师提出“是什么”“为什么”等问题，上至天文，下至地理，从远古到未来，无一不想从教师那里得到答案，这说明教师必须具备",
