        "analysis": "在斯金纳的操作性条件反射理论中，惩罚是指通过呈现厌恶刺激（或撤销愉快刺激）来减少不良行为发生的概率。老师要求小刚因旷课写检讨书，是呈现一个不愉快的刺激（写检讨），目的是减少旷课行为的发生，属于惩罚。A正强化是通过呈现愉快刺激增加行为；B负强化是通过撤销厌恶刺激增加行为；D泛化是指条件反射的扩散。"
